import math

def largest_prime_factor(n: int):
    # Check for some edge cases
    if n == 1:
        return 1
    if n % 2 == 0:
        return 2

    # Find the largest potential factor
    largest_factor = math.isqrt(n)
    for i in range(3, largest_factor + 1, 2):
        while n % i == 0:
            n //= i

    # If n is still greater than 2, then it's a prime number
    if n > 2:
        return n

    return largest_factor
